sys_script_include.script:
var EventActionHandler = Class.create();
EventActionHandler.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

  cancelEvent: function() {
    var eventId = this.getParameter('sysparm_event_id');
    var gr = new GlideRecord('x_1790233_event_ma_event_record');
    if (gr.get(eventId)) {
      gr.setValue('status', 'Cancelled');
      gr.update();
      return 'Event cancelled successfully';
    }
    return 'Event not found';
  },

  rescheduleEvent: function() {
    var eventId = this.getParameter('sysparm_event_id');
    var newDate = this.getParameter('sysparm_new_date');
    var gr = new GlideRecord('x_1790233_event_ma_event_record');
    if (gr.get(eventId)) {
      gr.setValue('event_date', newDate);
      gr.update();
      return 'Event rescheduled successfully';
    }
    return 'Event not found';
  },

  type: 'EventActionHandler'
});
